// Display data for the home-page device mock-up: ONE file, fixed values, no database and no real
// customer or leader. Everything is invented and deliberately ordinary -- a balance of a few thousand
// dollars, monthly returns of 2-6%, drawdowns and losing days included -- so nothing here reads as a
// promise. The leader names are fictional and do not belong to any account on the platform.
// Curves are generated by a small seeded generator, so they look natural (ups and downs) and are the
// same on every render of the server and the browser.

const DAY = 86_400_000;

function rng(seed: number) {
  // mulberry32: tiny, deterministic
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Start of today (UTC): the anchor every dated fixture counts back from. */
function todayStart() {
  const n = new Date();
  return Date.UTC(n.getUTCFullYear(), n.getUTCMonth(), n.getUTCDate());
}

// ---------------------------------------------------------------- avatars (initials, no network)
const HUES = [212, 262, 172, 32, 330];
export function initialsAvatar(name: string, i = 0) {
  const initials = name
    .split(/\s+/)
    .slice(0, 2)
    .map((w) => w[0])
    .join("")
    .toUpperCase();
  const hue = HUES[i % HUES.length];
  const svg =
    `<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 96 96'><defs><linearGradient id='g' x1='0' y1='0' x2='1' y2='1'>` +
    `<stop offset='0' stop-color='hsl(${hue} 70% 55%)'/><stop offset='1' stop-color='hsl(${(hue + 40) % 360} 70% 38%)'/></linearGradient></defs>` +
    `<rect width='96' height='96' fill='url(#g)'/><text x='48' y='60' font-family='Arial,sans-serif' font-size='38' font-weight='700' fill='white' text-anchor='middle'>${initials}</text></svg>`;
  return `data:image/svg+xml;utf8,${encodeURIComponent(svg)}`;
}

// ---------------------------------------------------------------- the wallet
/** Closed copied trades of the last 90 days (a natural mix of wins and losses): ~ +$396 in the last
 *  30 days, -$128 before that, so the 90-day line goes down, recovers and finishes up. */
export function walletTrades(): { pnl: number; closed_at: string }[] {
  const r = rng(20261);
  const start = todayStart();
  const make = (fromDay: number, toDay: number, n: number, target: number) => {
    const raw = Array.from({ length: n }, () => (r() - 0.46) * 150);
    const mean = raw.reduce((s, v) => s + v, 0) / n;
    const shift = (target - raw.reduce((s, v) => s + v, 0)) / n;
    void mean;
    return raw.map((v, i) => ({
      pnl: Math.round((v + shift) * 100) / 100,
      closed_at: new Date(start - (toDay - (i / n) * (toDay - fromDay)) * DAY + (10 + (i % 8)) * 3_600_000).toISOString(),
    }));
  };
  return [...make(31, 90, 26, -128), ...make(0, 30, 15, 396)].sort((a, b) => a.closed_at.localeCompare(b.closed_at));
}

