// ---------------------------------------------------------------- leaders (cards)
export type MockLeader = {
  provider_id: string;
  display_name: string;
  avatar_url: string;
  rating_score: number;
  tier: string;
  risk_level: string;
  trading_status: string;
  followers_count: number;
  min_copy_amount: number;
  aum_band: number;
  profit_share_pct: number;
  roi_30d: number;
  trades_30d: number;
  win_rate_30d: number;
  mdd_30d: number;
  sharpe_30d: number;
  roi_7d: number;
  trades_7d: number;
  win_rate_7d: number;
  mdd_7d: number;
  bio: string | null;
  spark: number[];
};

function curve(seed: number, n: number, drift: number, vol: number): number[] {
  const r = rng(seed);
  const out = [0];
  let v = 0;
  for (let i = 1; i < n; i++) {
    // a slow wave on top of noise gives believable pullbacks
    v += drift + (r() - 0.5) * vol + Math.sin(i / 4.2 + seed) * vol * 0.35;
    out.push(Math.round(v * 100) / 100);
  }
  return out;
}

const L = (i: number, name: string, p: Omit<MockLeader, "provider_id" | "display_name" | "avatar_url" | "spark" | "trading_status" | "bio">, sparkSeed: number, drift: number, vol: number): MockLeader => ({
  provider_id: `00000000-0000-4000-8000-00000000000${i}`,
  display_name: name,
  avatar_url: initialsAvatar(name, i),
  trading_status: "active",
  bio: null,
  spark: curve(sparkSeed, 30, drift, vol),
  ...p,
});

