/** Daily returns of the last 90 days (fractions): about +4% a month with a real drawdown in the middle. */
export function profileDaily(): { days: string[]; ret: number[] } {
  const r = rng(77);
  const start = todayStart();
  const days: string[] = [];
  const ret: number[] = [];
  for (let i = 89; i >= 0; i--) {
    days.push(new Date(start - i * DAY).toISOString().slice(0, 10));
    const phase = 89 - i;
    const wave = phase > 30 && phase < 48 ? -0.0016 : 0.0021; // a rough patch, then recovery
    ret.push(wave + (r() - 0.5) * 0.011);
  }
  return { days, ret };
}

